s32 searchPSSFXList(s32 name) {
    extern s32 strcmp(const char* a, const char* b);
    PaperSoundEffectData* entry;
    s32 i;

    entry = pssfxlist;
    if (name >= 0) {
        return name;
    }

    i = 0;
    while (i < 0x1092) {
        if (strcmp(*(char**)entry, (char*)name) == 0) {
            break;
        }
        i++;
        entry++;
    }

    if (i >= 0x1092) {
        i = 0;
    }
    return i;
}
